from collections import Counter

def transform(grid):
    if not grid:
        return grid

    # Find background (most common color)
    all_cells = [cell for row in grid for cell in row]
    bg = Counter(all_cells).most_common(1)[0][0]

    rows, cols = len(grid), len(grid[0])

    # Find dominant non-background color for each column
    col_dominants = []
    for c in range(cols):
        col_vals = [grid[r][c] for r in range(rows)]
        non_bg = Counter(x for x in col_vals if x != bg)
        if non_bg:
            dominant = non_bg.most_common(1)[0][0]
            col_dominants.append(dominant)
        else:
            col_dominants.append(bg)

    # Build output
    output = [[bg] * cols for _ in range(rows)]

    # Rows 0-3 are cleared to background
    for r in range(min(4, rows)):
        for c in range(cols):
            output[r][c] = bg

    # From row 4 onwards, fill each column with its dominant color
    for r in range(4, rows):
        for c in range(cols):
            output[r][c] = col_dominants[c]

    return output

